[
  {
    "id": "must_take_cart_before_shopping",
    "text": "A shopper is obliged to obtain a cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquireCart"
    },
    "justification": "The rule refers to the shopping role of taking a cart, not to any coordinate or store-specific location."
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper who leaves the store must leave while still having the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is expressed in terms of the exit action and cart possession, which are meaningful in any store layout."
  },
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "A shopper is forbidden to have a cart in a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    },
    "justification": "Single-file passage width is a layout-independent geometric relation, so the rule can apply to any narrow aisle in any store."
  },
  {
    "id": "no_cart_between_opposing_shelves",
    "text": "A shopper is forbidden to push or hold a cart while standing in an aisle flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenOpposingShelves"
        ]
      }
    },
    "justification": "Being between opposing shelves describes a functional aisle configuration rather than a named cell or region."
  },
  {
    "id": "park_before_entering_constricted_browsing_aisle",
    "text": "A shopper is forbidden to enter a constricted shelf-browsing aisle while still having a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "constrictedBrowsingAisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                "singleFileAisle",
                "betweenOpposingShelves"
              ]
            }
          ]
        }
      },
      "events": {
        "enterConstrictedBrowsingAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "constrictedBrowsingAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterConstrictedBrowsingAisleWithCart"
    },
    "justification": "The rule depends on aisle accessibility and shelf adjacency, not on the particular coordinates of this supermarket."
  },
  {
    "id": "cart_free_collection_in_constricted_aisle",
    "text": "A shopper is forbidden to interact with a shelf in a constricted browsing aisle while having a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "constrictedBrowsingAisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                "singleFileAisle",
                "betweenOpposingShelves"
              ]
            }
          ]
        }
      },
      "events": {
        "shelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelfInteraction",
          "constrictedBrowsingAisle",
          "hasCart"
        ]
      }
    },
    "justification": "The rule distinguishes shelf-service behaviour in cramped browsing spaces, a concept that transfers across layouts."
  },
  {
    "id": "park_cart_only_in_wide_clear_aisle",
    "text": "A shopper who parks a cart is forbidden to park it in a shelf-adjacent or cramped position rather than in a wide clear aisle.",
    "abstraction": {
      "state_properties": {
        "wideClearAisle": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "gt": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideClearAisle"
          }
        ]
      }
    },
    "justification": "The allowed parking place is defined by clearance and lack of shelf obstruction, not by a fixed parking coordinate."
  },
  {
    "id": "reclaim_cart_after_constricted_side_trip",
    "text": "After leaving a constricted browsing aisle without a cart, a shopper is obliged to reclaim a cart before the trip ends.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "constrictedBrowsingAisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                "singleFileAisle",
                "betweenOpposingShelves"
              ]
            }
          ]
        }
      },
      "events": {
        "leaveConstrictedBrowsingAisleWithoutCart": {
          "pre": {
            "and": [
              "constrictedBrowsingAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "not": "constrictedBrowsingAisle"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveConstrictedBrowsingAisleWithoutCart",
      "discharge": "hasCart"
    },
    "justification": "The trigger is based on completing a cart-free side trip from a cramped browsing aisle, which is independent of the aisle's coordinate location."
  }
]

